begin;
do $$
declare u uuid[]:=array[gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid()];
 e1 uuid:=gen_random_uuid();e2 uuid:=gen_random_uuid();e3 uuid:=gen_random_uuid(); old_session uuid:=gen_random_uuid();new_session uuid:=gen_random_uuid();r jsonb; i integer;num integer;
begin
 u[1]:=(select user_id from public.user_profiles where role='main_admin' and approval_status='approved' and retired_at is null and lower(email)='leonardolllmacalinaoisap@gmail.com');
 if u[1] is null then raise exception 'Fixture requires the sanitized baseline designated main-administrator record';end if;
 for i in 2..7 loop
  insert into auth.users(id,email,email_confirmed_at) values(u[i],u[i]||'@test.invalid',now());
  insert into public.user_profiles(user_id,full_name,role,approval_status,email) values(u[i],'Access fixture '||i,case when i=1 then 'main_admin' else 'student' end,'approved',case when i=1 then 'leonardolllmacalinaoisap@gmail.com' else u[i]||'@test.invalid' end);
 end loop;
 insert into auth.sessions(id,user_id,created_at) values(old_session,u[2],now());
 insert into public.events(id,name,latitude,longitude,radius_meters,starts_at,ends_at,institution) values(e1,'Scoped ISAP',17,121,100,now()-interval '1 hour',now()+interval '1 hour','ISAP'),(e2,'Scoped MCNP',17,121,100,now()-interval '1 hour',now()+interval '1 hour','MCNP'),(e3,'Schoolwide',17,121,100,now()-interval '1 hour',now()+interval '1 hour',null);
 perform set_config('role','service_role',true);
 r:=public.bootstrap_operational_administrator(u[1]);
 if r->>'role'<>'administrator' or not app_private.operational_capable(u[1],'accounts.manage') then raise exception 'FAIL: bootstrap';end if;
 begin perform public.bootstrap_operational_administrator(u[1]);raise exception 'FAIL: duplicate bootstrap';exception when sqlstate '22023' then null;end;
 begin perform public.save_operational_account(u[1],u[1],'col_regular','Root',true,1,'[]','{}','Remove root');raise exception 'FAIL: last administrator demotion';exception when sqlstate '22023' then null;end;
 begin perform public.save_operational_account(u[1],u[1],'administrator','Root',false,1,'[]','{}','Disable root');raise exception 'FAIL: last administrator deactivation';exception when sqlstate '22023' then null;end;
 r:=public.save_operational_account(u[1],u[2],'col_regular','Scoped regular',true,0,'[{"kind":"institution","scope_id":"ISAP"}]','{}','Assign ISAP');
 if not app_private.operational_capable(u[2],'events.view','event',e1::text) or app_private.operational_capable(u[2],'events.view','event',e2::text) or app_private.operational_capable(u[2],'events.view','event',e3::text) then raise exception 'FAIL: organizational scope';end if;
 r:=public.list_operational_events(u[2]);if not exists(select 1 from jsonb_array_elements(r) x where x->>'id'=e1::text) or exists(select 1 from jsonb_array_elements(r) x where x->>'id' in(e2::text,e3::text)) then raise exception 'FAIL: scoped event read';end if;
 begin perform public.list_operational_accounts(u[2]);raise exception 'FAIL: lower role lists accounts';exception when insufficient_privilege then null;end;
 begin perform public.save_operational_account(u[2],u[3],'administrator','Escalation',true,0,'[]','{}','Unauthorized promotion');raise exception 'FAIL: lower role promotion';exception when insufficient_privilege then null;end;
 begin perform public.save_operational_account(u[1],u[3],'classroom_representative','Class rep',true,0,'[{"kind":"institution","scope_id":"MCNP"}]','{}','Broad assignment');raise exception 'FAIL: representative broad scope';exception when sqlstate '22023' then null;end;
 r:=public.save_operational_account(u[1],u[3],'classroom_representative','Class rep',true,0,jsonb_build_array(jsonb_build_object('kind','event','scope_id',e2::text)),'{}','Explicit event assignment');
 if not app_private.operational_capable(u[3],'events.view','event',e2::text) or app_private.operational_capable(u[3],'events.view','event',e1::text) then raise exception 'FAIL: representative scope';end if;
 if not app_private.operational_capable(u[3],'reports.view','event',e2::text) or app_private.operational_capable(u[3],'reports.export','event',e2::text) then raise exception 'FAIL: representative report preview/export defaults';end if;
 r:=public.save_operational_account(u[1],u[4],'club_president','Club president',true,0,'[]','{}','No inferred assignments');
 if public.list_operational_events(u[4])<>'[]'::jsonb then raise exception 'FAIL: no scope defaults to global';end if;
 r:=public.save_operational_account(u[1],u[4],'club_president','Club president',true,1,jsonb_build_array(jsonb_build_object('kind','event','scope_id',e1::text)),'{"events.view":false,"reports.export":true}','Prepare explicit features');
 if app_private.operational_capable(u[4],'events.view') or not app_private.operational_capable(u[4],'reports.export','event',e1::text) or app_private.operational_capable(u[4],'reports.export','event',e2::text) then raise exception 'FAIL: override and scope';end if;
 begin perform public.list_operational_events(u[4]);raise exception 'FAIL: revoked event read';exception when insufficient_privilege then null;end;
 begin perform public.save_operational_account(u[1],u[4],'club_president','President',true,2,'[]','{"accounts.manage":true}','Forbidden override');raise exception 'FAIL: protected grant';exception when sqlstate '22023' then null;end;
 begin perform public.validate_operational_provision(u[1],'club_president','[]','{"unknown.feature":true}');raise exception 'FAIL: unknown preflight';exception when sqlstate '22023' then null;end;
 begin perform public.save_operational_account(u[1],u[4],'club_president','President',true,1,'[]','{}','Stale update');raise exception 'FAIL: stale version';exception when serialization_failure then null;end;
 r:=public.save_operational_account(u[1],u[5],'col_admin','COL admin',true,0,'[{"kind":"institution","scope_id":"MCNP"}]','{}','Scoped COL admin');
 if not app_private.operational_capable(u[5],'attendance.manual','event',e2::text) or app_private.operational_capable(u[5],'accounts.manage') then raise exception 'FAIL: COL admin defaults/security boundary';end if;
 begin perform public.save_operational_account(u[1],u[6],'student','Student',true,0,'[]','{}','Invalid role');raise exception 'FAIL: ordinary student operational role';exception when sqlstate '22023' then null;end;
 r:=public.enforce_operational_login(u[2],old_session,true);if r->>'active'<>'true' then raise exception 'FAIL: initial login';end if;
 perform public.record_operational_login(u[2],old_session,repeat('a',64),'Fixture browser','127.0.0.1');
 perform public.record_operational_login(u[2],old_session,repeat('a',64),'Fixture browser','127.0.0.1');
 select count(*) into num from public.login_logs where user_id=u[2];if num<>1 then raise exception 'FAIL: duplicate login logging';end if;
 r:=public.save_operational_account(u[1],u[2],'col_regular','Scoped regular',false,1,'[]','{}','Deactivate account');
 if (public.enforce_operational_login(u[2],old_session,false)->>'active')<>'false' or app_private.operational_capable(u[2],'events.view') then raise exception 'FAIL: disabled session retains access';end if;
 r:=public.save_operational_account(u[1],u[2],'col_regular','Scoped regular',true,2,'[]','{}','Reactivate account');
 if (public.enforce_operational_login(u[2],old_session,true)->>'active')<>'false' then raise exception 'FAIL: reactivation revives old token';end if;
 perform set_config('role','postgres',true);
 insert into auth.sessions(id,user_id,created_at) values(new_session,u[2],clock_timestamp());
 perform set_config('role','service_role',true);
 if (public.enforce_operational_login(u[2],new_session,true)->>'active')<>'true' or (public.enforce_operational_login(u[2],old_session,true)->>'active')<>'false' then raise exception 'FAIL: fresh login after reactivation';end if;
 r:=public.save_operational_account(u[1],u[7],'administrator','Second admin',true,0,'[]','{}','Add recovery administrator');
 r:=public.save_operational_account(u[7],u[1],'col_admin','Former root',true,1,'[]','{}','Reviewed demotion with surviving admin');
 if app_private.operational_capable(u[1],'accounts.manage') then raise exception 'FAIL: demotion stale grant';end if;
 begin perform public.save_operational_account(u[1],u[6],'administrator','User',true,0,'[]','{}','Stale actor');raise exception 'FAIL: revoked actor changes accounts';exception when insufficient_privilege then null;end;
 if not exists(select 1 from public.audit_logs where actor_user_id=u[7] and action='access.account_saved' and entity_id=u[1]::text) then raise exception 'FAIL: missing access audit';end if;
 for r in select jsonb_build_object('sig',p.oid::regprocedure::text) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('get_operational_access','enforce_operational_login','save_operational_account','bootstrap_operational_administrator','list_operational_events','list_operational_accounts','operational_account_candidates','record_operational_login','authorize_operational_invitation','validate_operational_provision') loop
  if has_function_privilege('anon',r->>'sig','EXECUTE') or has_function_privilege('authenticated',r->>'sig','EXECUTE') then raise exception 'FAIL: public operational RPC privilege';end if;
 end loop;
 if has_table_privilege('anon','public.operational_accounts','SELECT') or has_table_privilege('authenticated','public.operational_scopes','UPDATE') then raise exception 'FAIL: public access table privilege';end if;
end $$;
select 'PASS: operational roles, global/scoped boundaries, grants, version conflicts, administrator lockout, session revocation/reactivation, audit and private permissions' as result;
rollback;
